import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../services/auth.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {
  username = '';
  password = '';
  errorMessage = '';
  isLoading = false;

  constructor(private auth: AuthService, private router: Router) {}

  onSubmit(): void {
    this.errorMessage = '';

    if (!this.username || !this.password) {
      this.errorMessage = 'Please enter both username and password.';
      return;
    }

    this.isLoading = true;

    this.auth.login(this.username, this.password).subscribe({
      next: () => {
        this.isLoading = false;
        this.router.navigate(['/dashboard']);
      },
      error: (err) => {
        this.isLoading = false;
        // The backend sends a friendly message in err.error.message
        this.errorMessage = err.error?.message || 'Something went wrong. Please try again.';
      }
    });
  }
}
<div class="login-wrap">
  <div class="login-card">
    <div class="brand">
      <div class="brand-mark">MS</div>
      <div>
        <h1>MediaLedger</h1>
        <p class="tagline">Media Invoice Tracker</p>
      </div>
    </div>

    <form (ngSubmit)="onSubmit()">
      <label for="username">Username</label>
      <input id="username" type="text" [(ngModel)]="username" name="username" placeholder="admin" autocomplete="username" />

      <label for="password" class="password-label">Password</label>
      <input id="password" type="password" [(ngModel)]="password" name="password" placeholder="••••••••" autocomplete="current-password" />

      <p *ngIf="errorMessage" class="error-text">{{ errorMessage }}</p>

      <button type="submit" class="btn btn-primary submit-btn" [disabled]="isLoading">
        {{ isLoading ? 'Signing in...' : 'Sign in' }}
      </button>
    </form>

    <p class="hint">Try the demo account: <strong>admin</strong> / <strong>admin123</strong></p>
  </div>
</div>
